using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
[InitializeOnLoad] public static class InputV3Checks {
 const string Running="InputNineVirtualPlayChecks";
 static InputV3Checks(){if(SessionState.GetBool(Running,false))EditorApplication.update+=PlayEntry;}
 static void PlayEntry(){if(!EditorApplication.isPlaying||Time.frameCount<2)return;SessionState.SetBool(Running,false);EditorApplication.update-=PlayEntry;Run();}

 static int count;static List<string> rows;static string report;static void Check(bool ok,string name){rows.Add((ok?"PASS ":"FAIL ")+name);if(!ok)throw new Exception(name);count++;}
 static TrainingCommand[] Step(CharacterCommandResolver e,long f,int down,int held,CharacterDirectionalMove[] d=null)=>e.Sample(f,down,held,CharacterAttackSlot.AwariDefaults(),d);
 static GamepadState Pad(int mask,bool modifier=false){var state=new GamepadState();GamepadButton[] buttons={GamepadButton.West,GamepadButton.North,GamepadButton.RightShoulder,GamepadButton.South,GamepadButton.East};for(int i=0;i<5;i++)if((mask&(1<<i))!=0)state=state.WithButton(buttons[i]);if((mask&32)!=0)state.rightTrigger=1;state.leftTrigger=modifier?1:0;return state;}
 public static void Run(){if(!EditorApplication.isPlaying){UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Shioka/Scenes/CombatFormulaComparison.unity");SessionState.SetBool(Running,true);EditorApplication.update-=PlayEntry;EditorApplication.update+=PlayEntry;EditorApplication.EnterPlaymode();return;}rows=new List<string>();count=0;var args=Environment.GetCommandLineArgs();int ri=Array.IndexOf(args,"-inputV3Report");report=ri<0?"Temp/input-v3.txt":args[ri+1];try{Pure();Virtual();rows.Add(count+" PASS, 0 FAIL");File.WriteAllLines(report,rows);Debug.Log(rows.Last());EditorApplication.Exit(0);}catch(Exception e){rows.Add("EXCEPTION "+e);File.WriteAllLines(report,rows);Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Pure(){var e=new CharacterCommandResolver();var slots=CharacterAttackSlot.AwariDefaults();Check(e.Sample(100,64,64,slots,null).Single()==TrainingCommand.Light,"LP immediate on J");Check(e.Sample(101,7,7,slots,null).Length==0,"unassigned ABC no invented technique");Check(slots.Single(x=>x.slot==BattleAttackSlot.A).displayName=="D1"&&slots.Single(x=>x.slot==BattleAttackSlot.C).displayName=="D3","ABC character display names");var fixture=CharacterAttackSlot.AwariDefaults();fixture.Single(x=>x.slot==BattleAttackSlot.C).assigned=true;fixture.Single(x=>x.slot==BattleAttackSlot.C).command=TrainingCommand.Special;var buffer=new TrainingCommandBuffer();foreach(var cmd in e.Sample(102,256,256,fixture,null))buffer.Push(cmd);buffer.Advance(1f/60);foreach(var cmd in e.Sample(103,4,4,fixture,null))buffer.Push(cmd);Check(buffer.History.Select(x=>x.Command).SequenceEqual(new[]{TrainingCommand.Heavy,TrainingCommand.Special}),"normal HP retained before fixture D3");Check(buffer.TryTake(x=>x==TrainingCommand.Heavy,out var command)&&command==TrainingCommand.Heavy,"existing battle can select HP without rollback");buffer.ConfirmSelected(true);Check(!buffer.TryTake(x=>false,out command)&&buffer.Count==1,"D3 waits only in ordinary command buffer");for(int t=0;t<10;t++)buffer.Advance(1f/60);Check(buffer.Count==0,"ordinary expiry unchanged");var recorder=new TrainingRecorder();recorder.RecordKey();for(int t=0;t<180;t++)recorder.Tick(default);recorder.Tick(new TrainingInputFrame{AttackPressedMask=4,ForceHeld=true,RecordPressed=true});recorder.RecordKey();recorder.PlayKey();var f=recorder.Tick(default);Check(f.AttackPressedMask==4&&f.ForceHeld&&!f.RecordPressed,"logical ABC Mania record/play");Check(TrainingCommandHistory.Name(TrainingCommand.Throw)=="Hold","Hold display rename");}
 static void Virtual(){var old=InputSystem.settings;var temp=UnityEngine.Object.Instantiate(old);Keyboard keyboard=null;Gamepad pad=null;TrainingDeviceInput source=null;TrainingMenuInput menu=null;TrainingInputConfig config=null;try{temp.updateMode=InputSettings.UpdateMode.ProcessEventsManually;temp.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;temp.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=temp;keyboard=InputSystem.AddDevice<Keyboard>();pad=InputSystem.AddDevice<Gamepad>();config=UnityEngine.Object.Instantiate(Resources.Load<TrainingInputConfig>("TrainingInputConfig"));Check(config.ValidateV3(out var error),"new defaults valid "+error);source=new TrainingDeviceInput(config,false);source.Map.Enable();Action neutral=()=>{InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();source.Read(true);};Func<Key[],TrainingInputFrame> key=k=>{InputSystem.QueueStateEvent(keyboard,new KeyboardState(k));InputSystem.Update();return source.Read(true);};Func<GamepadState,bool,TrainingInputFrame> game=(state,training)=>{InputSystem.QueueStateEvent(pad,state);InputSystem.Update();return source.Read(training);};neutral();
 Key[] keys={Key.U,Key.I,Key.O,Key.J,Key.K,Key.L,Key.M,Key.Comma,Key.Period};int[] ids={0,1,2,6,7,8,3,4,5};for(int i=0;i<9;i++){neutral();Check(key(new[]{keys[i]}).AttackPressedMask==(1<<ids[i]),"keyboard slot "+((BattleAttackSlot)ids[i]));}for(int i=0;i<6;i++){neutral();int id=new[]{6,7,8,3,4,5}[i];Check(game(NewPad(1<<id),true).AttackPressedMask==(1<<id),"pad normal slot "+id);}
 neutral();InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.J));InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.Update();Check(source.Read(true).AttackPressedMask==64,"short tap retained");neutral();Check(key(new[]{Key.H}).Commands.Contains(TrainingCommand.Throw),"H Hold");neutral();Check(!key(new[]{Key.I}).Commands.Contains(TrainingCommand.Throw),"I is B not Hold");neutral();Check(key(new[]{Key.Semicolon}).Commands.Contains(TrainingCommand.Cancel),"semicolon TRC");neutral();Check(key(new[]{Key.Space}).DashPressed,"Space Dash");foreach(var shift in new[]{Key.LeftShift,Key.RightShift}){neutral();Check(key(new[]{shift}).ForceHeld,"independent Mania "+shift);}foreach(var ctrl in new[]{Key.LeftCtrl,Key.RightCtrl}){neutral();Check(key(new[]{ctrl}).Reset,"Ctrl reset "+ctrl);}neutral();Check(key(new[]{Key.R}).RecordPressed,"R Record");neutral();Check(key(new[]{Key.P}).PlayPressed,"P Play");
 foreach(int id in new[]{6,7,8,3,4,5}){neutral();var f=game(NewPad(1<<id,true),true);if(id==6)Check(f.AttackPressedMask==1,"T1 square A");if(id==7)Check(f.AttackPressedMask==2,"T1 triangle B");if(id==8)Check(f.AttackPressedMask==4,"T1 R1 C");if(id==3)Check(f.DashPressed&&f.AttackPressedMask==0,"T1 cross Dash");if(id==4)Check(f.Commands.Contains(TrainingCommand.Throw)&&f.AttackPressedMask==0,"T1 circle Hold");if(id==5)Check(f.Commands.Contains(TrainingCommand.Cancel)&&f.AttackPressedMask==0,"T1 R2 TRC");InputSystem.Update();f=source.Read(true);Check(f.AttackPressedMask==0&&!f.DashPressed&&f.Commands.Length==0,"no held chord repeats "+id);}
 neutral();var alone=game(NewPad(0,true),true);Check(alone.AttackPressedMask==0&&alone.Commands.Length==0&&!alone.ForceHeld,"L1 T1 alone inert");Check(game(NewPad(256,true),true).AttackPressedMask==4,"modifier before normal");neutral();InputSystem.QueueStateEvent(pad,NewPad(256));InputSystem.QueueStateEvent(pad,NewPad(256,true));InputSystem.Update();Check(source.Read(true).AttackPressedMask==4,"same tick chord suppresses HP");neutral();Check(game(NewPad(256),true).AttackPressedMask==256,"HP first immediate");Check(game(NewPad(256,true),true).AttackPressedMask==4,"late T1 emits fresh C");Check(game(NewPad(256,true),true).AttackPressedMask==0,"held does not repeat C");Check(game(NewPad(256,false),true).AttackPressedMask==0,"release T1 no HP ghost");Check(game(NewPad(256,true),true).AttackPressedMask==4,"reforming T1 chord emits C again");game(NewPad(0,true),true);Check(game(NewPad(256,true),true).AttackPressedMask==4,"face repress reforms C");neutral();var mania=game(NewPad(256,true,true),true);Check(mania.AttackPressedMask==4&&mania.ForceHeld,"Mania independent alongside ABC");neutral();Check(game(NewPad(0,false,true),true).ForceHeld,"L2 independent Mania");neutral();Check(game(new GamepadState().WithButton(GamepadButton.LeftStick),true).RecordPressed,"L3 Record");neutral();Check(game(new GamepadState().WithButton(GamepadButton.RightStick),true).PlayPressed,"R3 Play");neutral();Check(!game(new GamepadState().WithButton(GamepadButton.LeftStick),false).RecordPressed,"Record inert outside Training");neutral();Check(!game(new GamepadState().WithButton(GamepadButton.RightStick),false).PlayPressed,"Play inert outside Training");neutral();source.Clear();Check(game(NewPad(256,true),true).AttackPressedMask==0,"context boundary blocks held input");neutral();Check(game(NewPad(256,true),true).AttackPressedMask==4,"fresh chord after neutral");InputSystem.RemoveDevice(pad);pad=null;Check(!source.Read(true).ForceHeld,"disconnect clears state");pad=InputSystem.AddDevice<Gamepad>();neutral();config.modifier1Binding="<Gamepad>/leftTrigger";Check(!config.ValidateV3(out error),"T1 cannot share independent Mania");config.modifier1Binding="<Gamepad>/leftShoulder";config.slotGamepadBindings[7]=config.slotGamepadBindings[6];Check(!config.ValidateV3(out error),"duplicate physical chord rejected");config.slotGamepadBindings[7]="<Gamepad>/buttonNorth";
 menu=new TrainingMenuInput();InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.East));InputSystem.Update();Check(menu.Read(1).confirm,"menu circle confirm unchanged");InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.South));InputSystem.Update();Check(menu.Read(2).cancelFromPad,"menu cross cancel unchanged");InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.Start));InputSystem.Update();Check(menu.Read(3).option,"Options unchanged");InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.K));InputSystem.Update();Check(menu.Read(4).cancel&&!menu.Read(4).cancelFromPad,"text K distinguishable from pad cancel");
 }finally{menu?.Dispose();if(source!=null){source.Detach();source.Map.Dispose();}if(keyboard!=null)InputSystem.RemoveDevice(keyboard);if(pad!=null)InputSystem.RemoveDevice(pad);if(config!=null)UnityEngine.Object.DestroyImmediate(config);InputSystem.settings=old;UnityEngine.Object.DestroyImmediate(temp);}}
 static GamepadState NewPad(int mask,bool t1=false,bool mania=false){var s=new GamepadState();if((mask&64)!=0)s=s.WithButton(GamepadButton.West);if((mask&128)!=0)s=s.WithButton(GamepadButton.North);if((mask&256)!=0)s=s.WithButton(GamepadButton.RightShoulder);if((mask&8)!=0)s=s.WithButton(GamepadButton.South);if((mask&16)!=0)s=s.WithButton(GamepadButton.East);if((mask&32)!=0)s.rightTrigger=1;if(t1)s=s.WithButton(GamepadButton.LeftShoulder);s.leftTrigger=mania?1:0;return s;}
}
